require_once __DIR__ . '/../../cors.php';require_once __DIR__ . '/../../db/db.php';require_once __DIR__ . '/../../reusables/organization_guard.php';header('Content-Type: application/json');$ctx=requireOrganizationAccess($pdo,'analytics.reports.read');$org=(int)$ctx['organization_id'];
try{$s=$pdo->prepare("SELECT (SELECT COUNT(*) FROM dispatch_assignments WHERE organization_id=?) missions_total,(SELECT COUNT(*) FROM dispatch_assignments WHERE organization_id=? AND assignment_status='completed') completed,(SELECT COUNT(*) FROM dispatch_assignments WHERE organization_id=? AND assignment_status NOT IN ('completed','cancelled','declined')) active,(SELECT COUNT(*) FROM incident_offers WHERE organization_id=? AND offer_status='accepted') offers_accepted,(SELECT COUNT(*) FROM incident_offers WHERE organization_id=? AND offer_status='declined') offers_declined,(SELECT COUNT(*) FROM incident_offers WHERE organization_id=? AND offer_status='timed_out') offers_timed_out,(SELECT COUNT(*) FROM ambulances WHERE organization_id=? AND deleted_at IS NULL) fleet_total,(SELECT COUNT(*) FROM ambulances WHERE organization_id=? AND deleted_at IS NULL AND status='available') fleet_available,(SELECT COUNT(*) FROM organization_members WHERE organization_id=? AND deleted_at IS NULL AND membership_status='active') members_active,(SELECT COUNT(*) FROM personnel_profiles pp JOIN organization_members om ON om.id=pp.organization_member_id WHERE om.organization_id=? AND om.deleted_at IS NULL AND pp.availability_status='available') personnel_available");$s->execute(array_fill(0,10,$org));$stats=$s->fetch(PDO::FETCH_ASSOC)?:[];$perf=$pdo->prepare("SELECT ROUND(AVG(TIMESTAMPDIFF(MINUTE,assigned_at,arrived_at)),1) avg_response_minutes,ROUND(AVG(TIMESTAMPDIFF(MINUTE,assigned_at,completed_at)),1) avg_mission_minutes FROM dispatch_assignments WHERE organization_id=? AND arrived_at IS NOT NULL");$perf->execute([$org]);$performance=$perf->fetch(PDO::FETCH_ASSOC)?:[];$daily=$pdo->prepare("SELECT DATE(assigned_at) day,COUNT(*) count FROM dispatch_assignments WHERE organization_id=? AND assigned_at>=DATE_SUB(CURDATE(),INTERVAL 13 DAY) GROUP BY DATE(assigned_at) ORDER BY day");$daily->execute([$org]);echo json_encode(['success'=>true,'stats'=>array_map('intval',$stats),'performance'=>$performance,'daily'=>$daily->fetchAll(PDO::FETCH_ASSOC)]);}catch(Throwable $e){error_log('Org reports failed: '.$e->getMessage());organizationJsonError(500,'Unable to load organization reports.');}
